const easingNames={'linear':'线性','ease-in':'缓入','ease-out':'缓出','ease-in-out':'缓入缓出','hold':'保持'};
function easingTarget(c){const keys=c.keyframes||[],time=keyframeTime(c),key=keys.find(k=>Math.abs(k.time-time)<.0011)||keys.find(k=>k.time>time);return key&&key.time>0?key:null;}
function easingInspector(c){const key=easingTarget(c),type=key?.easing||'linear',window=key?.easingWindow,curve=[];for(let i=0;i<=48;i++){const x=i/48,y=M.normalizedEasingProgress?M.normalizedEasingProgress(type,x,window):x;curve.push(`${i?'L':'M'}${4+x*172},${60-y*56}`);}return `<label class="field full easing-field">进入关键帧的变化<select data-keyframe-easing ${key?'':'disabled'} aria-label="关键帧缓动">${Object.entries(easingNames).map(([value,label])=>`<option value="${value}" ${type===value?'selected':''}>${label}</option>`).join('')}</select></label><div class="easing-preview"><svg viewBox="0 0 180 64" role="img" aria-label="${easingNames[type]}曲线"><path class="easing-grid" d="M4 4V60H176M4 32H176M90 4V60"/><path class="easing-curve" d="${curve.join(' ')}"/></svg><span>${key?'到 '+num(key.time)+'s':(c.keyframes?.length?'选择时间大于 0 的关键帧':'添加关键帧后设置')}</span></div><p class="field-help">${key?(type==='hold'?'保持前一帧的值，到目标帧时切换。':'控制前一帧到目标帧的速度，不改变起点与终点。'):'在关键帧之间时，修改的是播放头之后的目标帧。'}${window&&(window[0]!==0||window[1]!==1)?' 已保留剪切前的曲线；重新选取缓动会重设此段。':''}</p>`;}
function refreshEasingFields(c){const target=easingTarget(c),signature=JSON.stringify([target?.time,target?.easing,target?.easingWindow,c.keyframes?.length]),host=$('easingControls');if(host&&host.dataset.signature!==signature){host.innerHTML=easingInspector(c);host.dataset.signature=signature;}}
