 for(const element of [item.media,item.canvas])Object.assign(element.style,{position:'absolute',inset:'auto',width:`${a.width*factor}px`,height:`${a.height*factor}px`,left:`${-r.x*factor}px`,top:`${-r.y*factor}px`,objectFit:'fill'});
