 const signature=JSON.stringify([width,height,visuals.map(c=>[c.id,visualNodes.get(c.id)?.colorSignature||'',visualNodes.get(c.id)?.colorRevision||0,c.crop,c.mask,c.maskAnimation,c.visualEffects,c.flipX,c.flipY,poseAt(c,previewTime()),M.visualOpacity?M.visualOpacity(project,c,previewTime()):poseAt(c).opacity])]);
