  const r=M.cropRect(a,c),pose=poseAt(c,previewTime()),fit=Math.min(width/r.width,height/r.height),drawWidth=r.width*fit,drawHeight=r.height*fit;
  context.save();context.globalCompositeOperation=Visual.canvasBlend(c.visualEffects?.blendMode||'normal');context.globalAlpha=clamp(M.visualOpacity?M.visualOpacity(project,c,previewTime()):pose.opacity,0,1);context.translate(width/2+pose.x*width,height/2+pose.y*height);context.rotate(pose.rotation*Math.PI/180);context.scale(pose.scale*(c.flipX?-1:1),pose.scale*(c.flipY?-1:1));
