async function openDemo(){if(state.busy||!desktopRequired()||!discardAllowed())return;pause();state.replacing=true;state.busy=true;updateButtons();try{const p=await api.openDemo();replaceProject(p.project||p,'',true);notify('演示已加载，可直接播放或开始剪辑');}catch(error){reportError(error);}finally{state.replacing=false;state.busy=false;updateButtons();updateEngineStatus();}}
function openExport(){workflowControls?.refreshExport();if(!state.export.active&&!state.export.pending&&!['completed','canceled','error'].includes(state.export.status)){$('exportWidth').value=project.width;$('exportHeight').value=project.height;const f=String(project.fps);if(![...$('exportFps').options].some(o=>o.value===f))$('exportFps').add(new Option(f,f));$('exportFps').value=f;updateResolutionPreset();$('exportForm').hidden=false;$('exportProgressPanel').hidden=true;}$('exportDuration').textContent=timecode(duration(),false);$('exportAvailability').textContent=!api?'请在桌面应用中启动后导出。':state.environment&&!state.environment.ffmpegAvailable?'没有检测到 FFmpeg，请完成桌面引擎配置后导出。':duration()<=0?'请先将素材或字幕添加到时间线。':'画布设置用于预览与导出。SDR 显示兼容模式 · 预览与导出使用统一颜色。';const missing=usedOfflineAssets();if(missing.length)$('exportAvailability').textContent=`请先定位 ${missing.length} 个已使用的缺失素材：${missing.map(a=>a.name).join('、')}`;$('startExport').disabled=!api||duration()<=0||state.environment?.ffmpegAvailable===false||missing.length>0;if(!$('exportDialog').open)$('exportDialog').showModal();}
function updateResolutionPreset(){const value=`${$('exportWidth').value}x${$('exportHeight').value}`;$('resolutionPreset').value=[...$('resolutionPreset').options].some(o=>o.value===value)?value:'custom';}
function canvasSettings(){const width=Number($('exportWidth').value),height=Number($('exportHeight').value),fps=Number($('exportFps').value);if(!Number.isInteger(width)||!Number.isInteger(height)||width<64||height<64||width>7680||height>7680||width%2||height%2)throw new Error('画布宽高需要是 64–7680 之间的偶数。');if(!Number.isFinite(fps)||fps<=0||fps>120)throw new Error('帧率需在 1–120 之间。');return {width,height,fps};}
function applyCanvas(close=true){try{const settings=canvasSettings();if(settings.width!==project.width||settings.height!==project.height||settings.fps!==project.fps)customEdit(p=>{const ratio=settings.height/p.height,TS=window.EditorTextStyle;if(ratio!==1&&TS.usesCanvas(p))for(const [kind,cues]of [['subtitle',p.subtitles],['text',p.texts||[]]])for(const cue of cues){const style=TS.normalizeStyle(cue.style||{},p,kind);for(const key of ['fontSize','letterSpacing','padding','outlineWidth','shadowBlur','shadowX','shadowY'])style[key]*=ratio;cue.style=style;}p.subtitleStyle.fontSize*=ratio;Object.assign(p,settings);},'画布设置已应用');if(close)$('exportDialog').close();return settings;}catch(error){reportError(error);return null;}}
function renderExportProgress(){const e=state.export;$('exportForm').hidden=true;$('exportProgressPanel').hidden=false;$('exportProgress').value=e.progress;$('exportPercent').textContent=`${Math.round(e.progress*100)}%`;$('exportStatus').textContent=e.status==='completed'?'导出完成':e.status==='canceled'?'导出已取消':e.status==='error'?'导出未完成':e.pending?'正在选择保存位置…':'正在导出视频';$('exportDetail').textContent=e.error||(e.status==='completed'?e.path:e.status==='canceled'?'你可以调整项目后重新导出。':'导出期间可以关闭此窗口，进度会显示在顶部。');$('cancelExport').hidden=!e.active&&!e.pending;$('cancelExport').disabled=!e.jobId||e.pending;$('revealExport').hidden=e.status!=='completed'||!e.path;$('exportAgain').hidden=e.active||e.pending;updateButtons();}
async function startExport(){if(!desktopRequired())return;const settings=applyCanvas(false);if(!settings)return;pause();state.export={jobId:null,active:false,pending:true,progress:0,status:'',path:'',error:''};renderExportProgress();try{const result=await api.exportProject(clone(project),{...settings,...workflowControls.exportSettings()});if(result?.canceled){state.export.pending=false;state.export.status='canceled';renderExportProgress();return;}state.export.jobId=result.jobId;state.export.path=result.path||state.export.path;state.export.pending=false;if(!['completed','error','canceled'].includes(state.export.status)){state.export.active=true;state.export.status='running';}renderExportProgress();}catch(error){state.export.pending=false;state.export.active=false;state.export.status='error';state.export.error=error.message||String(error);renderExportProgress();}}
function exportProgress(event){const e=state.export;if(e.jobId&&event.jobId!==e.jobId)return;if(!e.active&&!e.pending&&!e.jobId)return;e.jobId=event.jobId||e.jobId;e.pending=false;e.progress=clamp(Number(event.progress)||0,0,1);e.status=event.status||'running';e.path=event.path||e.path;e.error=event.error||'';e.active=!['completed','canceled','error'].includes(e.status);if(e.status==='completed'){e.progress=1;notify('视频导出完成');}else if(e.status==='error')notify(e.error||'导出失败，请查看错误信息。',true);renderExportProgress();}
async function cancelExport(){if(!state.export.jobId)return;$('cancelExport').disabled=true;try{await api.cancelExport(state.export.jobId);}catch(error){reportError(error);$('cancelExport').disabled=false;}}
async function openAsr(){if(!desktopRequired())return;pause();if(!$('asrDialog').open)$('asrDialog').showModal();if(state.asr.status){renderAsrProgress();return;}$('asrSetup').hidden=false;$('asrProgressPanel').hidden=true;$('asrAvailability').textContent='正在检查本地识别模型…';$('startAsr').disabled=true;try{const status=await api.getAsrStatus();state.asrAvailability=status;$('asrAvailability').textContent=status.available?`本地模型已就绪 · ${status.model||'Whisper multilingual'}。纯音乐或没有人声的片段可能不会生成字幕。`:(status.reason||'本地识别模型尚未就绪。');$('startAsr').disabled=!status.available||!project.clips.length||state.export.active||state.export.pending;if(state.export.active||state.export.pending)$('asrAvailability').textContent='请先等待视频导出完成，或取消导出后开始识别。';}catch(error){$('asrAvailability').textContent=error.message||String(error);}}
function renderAsrProgress(){const a=state.asr;$('asrSetup').hidden=true;$('asrProgressPanel').hidden=false;$('asrProgress').value=a.progress;$('asrPercent').textContent=`${Math.round(a.progress*100)}%`;$('asrStatus').textContent=a.status==='completed'?'识别完成':a.status==='canceled'?'识别已取消':a.status==='error'?'识别未完成':a.stage==='preparing'?'正在准备音频':'正在识别人声';$('asrDetail').textContent=a.error||(a.status==='completed'?(a.cues.length?`生成 ${a.cues.length} 条字幕。检查下方内容后写入时间线；之后可以撤销。`:'没有识别到可用人声。请检查片段音量和内容。'):a.status==='canceled'?'识别已停止，原字幕未改变。':a.message||'正在本机处理，首次识别可能需要一点时间。');$('cancelAsr').hidden=!a.active&&!a.pending;$('cancelAsr').disabled=!a.jobId||a.pending;$('closeAsr').disabled=a.active||a.pending;$('retryAsr').hidden=a.active||a.pending;$('applyAsr').hidden=a.status!=='completed'||!a.cues.length;$('applyAsr').disabled=Boolean(a.applied);if(a.status==='completed'&&!a.rendered){$('asrCues').innerHTML=a.cues.map((cue,i)=>`<div class="asr-cue"><span>${String(i+1).padStart(2,'0')}</span><div><div class="asr-cue-time"><input type="number" min="0" step=".01" value="${num(cue.start)}" data-asr-cue="${i}" data-asr-prop="start" aria-label="第 ${i+1} 条字幕开始时间"><span>→</span><input type="number" min="0" step=".01" value="${num(cue.end)}" data-asr-cue="${i}" data-asr-prop="end" aria-label="第 ${i+1} 条字幕结束时间"><span>秒</span></div><textarea data-asr-cue="${i}" data-asr-prop="text" aria-label="第 ${i+1} 条识别文字">${esc(cue.text)}</textarea></div></div>`).join('');a.rendered=true;}else if(a.status!=='completed')$('asrCues').replaceChildren();}
async function startAsr(){if(!desktopRequired()||state.asr.active||state.asr.pending)return;pause();state.asr={active:false,pending:true,jobId:null,status:'running',progress:0,cues:[],snapshot:JSON.stringify(project),mode:$('asrMode').value,error:'',stage:'preparing',rendered:false,applied:false};renderAsrProgress();try{const result=await api.startTranscription(clone(project),{language:$('asrLanguage').value});state.asr.jobId=result.jobId;state.asr.pending=false;if(!['completed','error','canceled'].includes(state.asr.status))state.asr.active=true;renderAsrProgress();}catch(error){state.asr.pending=false;state.asr.active=false;state.asr.status='error';state.asr.error=error.message||String(error);renderAsrProgress();}}
function transcriptionProgress(event){const a=state.asr;if(a.jobId&&event.jobId!==a.jobId)return;if(!a.active&&!a.pending&&!a.jobId)return;a.jobId=event.jobId||a.jobId;a.pending=false;a.progress=clamp(Number(event.progress)||0,0,1);a.status=event.status||'running';a.stage=event.stage||a.stage;a.message=event.message||'';a.error=event.error||'';a.active=!['completed','canceled','error'].includes(a.status);if(a.status==='completed'){a.progress=1;a.cues=clone(event.cues||[]);a.rendered=false;}renderAsrProgress();}
async function cancelAsr(){if(!state.asr.jobId)return;$('cancelAsr').disabled=true;try{await api.cancelTranscription(state.asr.jobId);}catch(error){reportError(error);$('cancelAsr').disabled=false;}}
function applyAsr(){const a=state.asr;if(a.status!=='completed'||a.applied)return;if(JSON.stringify(project)!==a.snapshot){notify('项目在识别后发生了变化，请返回设置后重新识别。',true);return;}if(edit(p=>{let next=p;if(a.mode==='replace')next.subtitles=[];for(const cue of a.cues)next=M.addSubtitle(next,{start:Number(cue.start),end:Number(cue.end),text:String(cue.text)});return next;},`已写入 ${a.cues.length} 条自动字幕，可继续编辑与撤销`)){a.applied=true;state.library='subtitle';renderLibrary();$('asrDialog').close();a.status='';a.jobId=null;}}

function cancelRecoveryTimer(){clearTimeout(recovery.timer);recovery.timer=0;recovery.epoch++;}
function clearRecovery(discardUnresolved=false){cancelRecoveryTimer();if(!discardUnresolved&&(!recovery.ready||recovery.unresolved))return Promise.resolve(false);recovery.statusEpoch++;recovery.ready=true;recovery.unresolved=false;recovery.invalid=false;recovery.savedAt='';$('recoveryBanner').hidden=true;if(!api?.clearRecovery)return Promise.resolve();recovery.queue=recovery.queue.catch(()=>{}).then(()=>api.clearRecovery()).catch(error=>{reportError(new Error('无法清除自动暂存：'+(error.message||error)));});return recovery.queue;}
function scheduleRecovery(){clearTimeout(recovery.timer);if(!recovery.ready||recovery.unresolved||!api?.saveRecovery)return;if(!dirty()){clearRecovery();return;}const epoch=recovery.epoch;recovery.timer=setTimeout(()=>{const snapshot=clone(project);recovery.queue=recovery.queue.catch(()=>{}).then(async()=>{if(epoch!==recovery.epoch||recovery.unresolved)return;const result=await api.saveRecovery(snapshot);if(epoch!==recovery.epoch)return;recovery.savedAt=result.savedAt||'';recovery.lastError='';$('projectSaveState').title='最近自动暂存：'+new Date(recovery.savedAt).toLocaleString();}).catch(error=>{const message=error.message||String(error);if(recovery.lastError!==message){recovery.lastError=message;reportError(new Error('自动暂存失败，请手动保存项目：'+message));}});},1000);}
async function initializeRecovery(){if(!api?.getRecoveryStatus){recovery.ready=true;return;}const epoch=recovery.statusEpoch;try{const status=await api.getRecoveryStatus();if(epoch!==recovery.statusEpoch)return;recovery.ready=true;recovery.unresolved=Boolean(status?.available);if(recovery.unresolved){$('recoveryMessage').textContent=`发现上次自动暂存的「${status.name||'未命名项目'}」${status.savedAt?' · '+new Date(status.savedAt).toLocaleString():''}。恢复或忽略前，当前工程不会自动暂存。`;$('recoveryBanner').hidden=false;}else scheduleRecovery();}catch(error){if(epoch!==recovery.statusEpoch)return;recovery.ready=true;recovery.unresolved=true;recovery.invalid=true;$('recoveryMessage').textContent='上次自动暂存无法读取，原记录已保留。忽略后可重新自动暂存。';$('recoveryBanner').hidden=false;updateButtons();reportError(new Error('无法检查自动暂存：'+(error.message||error)));}}
async function restoreRecovery(){if(state.busy||!desktopRequired()||!discardAllowed())return;cancelRecoveryTimer();pause();state.replacing=true;state.busy=true;updateButtons();$('statusMessage').textContent='正在恢复暂存项目并准备素材…';try{await recovery.queue;const result=await api.restoreRecovery();if(result?.canceled)return;replaceProject(result.project,'',true,true);recovery.ready=true;recovery.unresolved=false;$('recoveryBanner').hidden=true;scheduleRecovery();notify('已恢复自动暂存，请另存项目以保留修改');}catch(error){reportError(error);}finally{state.replacing=false;state.busy=false;updateButtons();updateEngineStatus();}}
async function exportSrt(){if(state.busy||!desktopRequired()||!project.subtitles.length)return;document.activeElement?.blur();state.busy=true;updateButtons();try{const result=await api.exportSubtitles(clone(project));if(!result?.canceled)notify('SRT 字幕已导出');}catch(error){reportError(error);}finally{state.busy=false;updateButtons();updateEngineStatus();}}

function updateEngineStatus(){if(state.busy||!$('cancelImport').hidden)return;const available=state.environment?.ffmpegAvailable;$('engineDot').className=`status-light${!api?' muted':available===false?' warning':''}`;$('statusMessage').textContent=!api?'桌面接口未连接':available===false?'本地引擎未就绪 · 未检测到 FFmpeg':state.environment?`本地编辑 · ${state.environment.version?'映序 '+state.environment.version:'引擎已就绪'}`:'正在连接本地引擎…';}

