$('projectName').addEventListener('keydown',e=>{if(e.key==='Enter')e.target.blur();});
$('newProject').onclick=()=>{if(!state.busy&&discardAllowed())replaceProject(M.createProject('未命名项目'));};
$('openProject').onclick=openProject;$('saveProject').onclick=saveProject;$('openDemo').onclick=openDemo;
$('restoreRecovery').onclick=restoreRecovery;$('ignoreRecovery').onclick=async()=>{await clearRecovery(true);updateButtons();scheduleRecovery();};$('exportSrt').onclick=exportSrt;
$('importMedia').onclick=()=>importAssets();$('importSrt').onclick=importSrt;$('autoSubtitle').onclick=openAsr;$('startAsr').onclick=startAsr;$('cancelAsr').onclick=cancelAsr;$('applyAsr').onclick=applyAsr;$('closeAsr').onclick=()=>{if(!state.asr.active&&!state.asr.pending)$('asrDialog').close();};$('asrDialog').addEventListener('cancel',e=>{if(state.asr.active||state.asr.pending)e.preventDefault();});$('retryAsr').onclick=()=>{state.asr.status='';state.asr.jobId=null;openAsr();};$('asrCues').addEventListener('input',e=>{const index=e.target.dataset.asrCue,prop=e.target.dataset.asrProp;if(index===undefined||!prop)return;const cue=state.asr.cues[Number(index)];if(cue)cue[prop]=prop==='text'?e.target.value:Number(e.target.value);});
