$('inspectorBody').addEventListener('click',e=>{if(e.target.closest('[data-inspector-delete]'))removeSelection();const b=e.target.closest('[data-inspector-add]');if(b)addAssetToTimeline(b.dataset.inspectorAdd);const c=selectedClip();if(!c)return;if(e.target.closest('[data-keyframe-add]'))edit(p=>M.setClipKeyframe(p,c.id,keyframeTime(c),poseAt(c)));if(e.target.closest('[data-keyframe-delete]'))edit(p=>M.removeClipKeyframe(p,c.id,keyframeTime(c)));const key=e.target.closest('[data-keyframe-time]');if(key){pause();seek(c.start+Number(key.dataset.keyframeTime));}});
