window.EditorAdvancedControls.install($('inspectorBody'),{getClip:selectedClip,updateClip:(patch,message)=>{const c=selectedClip();if(c&&!edit(p=>M.updateClip(p,c.id,patch),message))renderInspector();},reportError});
$('inspectorBody').addEventListener('change',e=>{const prop=e.target.dataset.prop,text=e.target.dataset.subtitleProp,c=selectedClip(),s=selectedSubtitle(),motion=e.target.dataset.transformProp,transition=e.target.dataset.transitionProp;
const maskProp=e.target.dataset.maskProp;
if(e.target.matches('[data-keyframe-easing]')&&c){const key=easingTarget(c);if(key)edit(p=>M.setClipKeyframe(p,c.id,key.time,poseAt(c,c.start+key.time),{easing:e.target.value}));return;}
if(maskProp&&c){if(maskProp==='type'&&e.target.value==='none')edit(p=>M.updateClip(p,c.id,{mask:null}));else{const mask=Object.assign({type:'rectangle',centerX:.5,centerY:.5,width:1,height:1,rotation:0,feather:0,invert:false},c.mask);mask[maskProp]=maskProp==='type'?e.target.value:maskProp==='invert'?e.target.checked:Number(e.target.value)/(maskProp==='rotation'?1:100);edit(p=>M.updateClip(p,c.id,{mask}));}return;}
const cropProp=e.target.dataset.cropProp,flipProp=e.target.dataset.flipProp,colorProp=e.target.dataset.colorProp,fadeProp=e.target.dataset.fadeProp;
if(cropProp&&c){edit(p=>M.updateClip(p,c.id,{crop:Object.assign({left:0,top:0,right:0,bottom:0},c.crop,{[cropProp]:Number(e.target.value)/100})}));return;}
if(flipProp&&c){edit(p=>M.updateClip(p,c.id,{[flipProp]:e.target.checked}));return;}
if(colorProp&&c){edit(p=>M.updateClip(p,c.id,{color:Object.assign({brightness:0,contrast:0,saturation:0},c.color,{[colorProp]:Number(e.target.value)/colorControlRange(colorProp)})}));return;}
if(fadeProp&&c){edit(p=>M.updateClip(p,c.id,{audioFade:Object.assign({in:0,out:0},c.audioFade,{[fadeProp]:Number(e.target.value)})}));return;}
if(motion&&c){const pose=poseAt(c);pose[motion]=Number(e.target.value)/(motion==='rotation'?1:100);if(c.keyframes?.length)edit(p=>M.setClipKeyframe(p,c.id,keyframeTime(c),pose));else edit(p=>M.updateClip(p,c.id,{transform:pose}));return;}
if(transition&&c){const peers=project.clips.filter(x=>x.track==='video'&&!clipLayer(x)),prev=peers[peers.findIndex(x=>x.id===c.id)-1];if(!prev)return;const patch={type:c.transition?.type||'crossfade',duration:c.transition?.duration||Math.min(.5,prev.duration/2,c.duration/2)};if(transition==='type')patch.type=e.target.value;else patch.duration=Number(e.target.value);edit(p=>M.setClipTransition(p,c.id,patch.type==='none'?null:patch));return;}
if(text&&s){edit(p=>M.updateSubtitle(p,s.id,{text:e.target.value}));return;}if(!prop)return;if(prop==='fontSize'||prop==='subtitleColor'){customEdit(p=>{p.subtitleStyle[prop==='fontSize'?'fontSize':'color']=prop==='fontSize'?Number(e.target.value):e.target.value;});return;}if((prop==='subtitleStart'||prop==='subtitleEnd')&&s){edit(p=>M.updateSubtitle(p,s.id,{[prop==='subtitleStart'?'start':'end']:Number(e.target.value)}));return;}if(c){const patch={[prop]:prop==='volume'?Number(e.target.value)/100:Number(e.target.value)};if(prop==='sourceIn'){const a=assetById(c.assetId);if(a.kind!=='image')patch.duration=c.speedCurve?Math.min(c.duration,M.clipLocalTimeForSource(c,c.sourceIn+Math.max(0,a.duration-patch.sourceIn))):Math.min(c.duration,Math.max(0,(a.duration-patch.sourceIn)/c.speed));}if(prop==='layer'){state.layerCount=Math.max(state.layerCount,patch.layer);state.activeLayer=patch.layer;patch.start=c.start;}edit(p=>M.updateClip(p,c.id,patch));}});
$('inspectorBody').addEventListener('click',e=>{const c=selectedClip();if(!c)return;if(e.target.closest('[data-mask-reset]'))edit(p=>M.updateClip(p,c.id,{mask:null}));if(e.target.closest('[data-crop-reset]'))edit(p=>M.updateClip(p,c.id,{crop:{left:0,top:0,right:0,bottom:0},flipX:false,flipY:false}));if(e.target.closest('[data-color-reset]'))edit(p=>M.updateClip(p,c.id,{color:{brightness:0,contrast:0,saturation:0}}));});
$('timelineContent').addEventListener('dragstart',e=>{const c=e.target.closest('[data-clip-id]');if(c){e.dataTransfer.setData('application/x-yingxu-clip',c.dataset.clipId);e.dataTransfer.effectAllowed='move';}});
function scrub(e){if(e.button!==0)return;e.preventDefault();pause();const move=event=>seek((event.clientX-$('timelineContent').getBoundingClientRect().left)/state.zoom);move(e);window.addEventListener('pointermove',move);window.addEventListener('pointerup',()=>window.removeEventListener('pointermove',move),{once:true});}
$('timelineRuler').addEventListener('pointerdown',scrub);$('playhead').addEventListener('pointerdown',scrub);
$('timelineContent').addEventListener('dragover',e=>{const track=e.target.closest('.track');if(!track||track.dataset.track==='subtitle')return;e.preventDefault();track.classList.add('drag-over');e.dataTransfer.dropEffect=e.dataTransfer.types.includes('application/x-yingxu-clip')?'move':'copy';});
$('timelineContent').addEventListener('dragleave',e=>{const track=e.target.closest('.track');if(track&&!track.contains(e.relatedTarget))track.classList.remove('drag-over');});
$('timelineContent').addEventListener('drop',e=>{const track=e.target.closest('.track');if(!track)return;track.classList.remove('drag-over');const assetId=e.dataTransfer.getData('application/x-yingxu-asset'),clipId=e.dataTransfer.getData('application/x-yingxu-clip');if(!assetId&&!clipId)return;e.preventDefault();e.stopPropagation();const t=Math.max(0,(e.clientX-$('timelineContent').getBoundingClientRect().left)/state.zoom),layer=Number(track.dataset.layer)||0;
if(assetId){const a=assetById(assetId);if(!a)return;const expected=a.kind==='audio'?'audio':'video';if(track.dataset.track!==expected){notify(`请将${kindName(a.kind)}放到${expected==='audio'?'音频':'视频'}轨。`);return;}state.activeLayer=layer;addAssetToTimeline(assetId,t,layer,track.dataset.audioTrackId);}else{const c=project.clips.find(x=>x.id===clipId);if(!c||c.track!==track.dataset.track)return;if(project.magneticMain===false)edit(p=>M.moveClips(p,[c.id],t-c.start,c.track==='video'?{layer}:{}));else if(c.track==='audio')edit(p=>M.updateClip(p,c.id,{start:num(t)}));else if(layer||clipLayer(c)!==layer){state.activeLayer=layer;edit(p=>M.updateClip(p,c.id,{layer,start:num(t)}));}else{const peers=project.clips.filter(x=>x.track==='video'&&!clipLayer(x)),from=peers.findIndex(x=>x.id===clipId),target=peers.filter(x=>x.id!==clipId&&x.start+x.duration/2<t).length;if(from!==target)edit(p=>{let next=p;for(let i=0;i<Math.abs(target-from);i++)next=M.reorderClip(next,clipId,Math.sign(target-from));return next;});}}});
$('addVideoTrack').onclick=()=>{const layer=maxLayer()+1;if(layer>8)return;state.layerCount=layer;state.activeLayer=layer;customEdit(p=>{p.videoTrackCount=layer+1;},`已添加视频 ${layer+1}，双击素材或拖入此轨`);};
function chooseLayer(e){const track=e.target.closest('[data-layer]');if(track){state.activeLayer=Number(track.dataset.layer);renderTimeline();notify(`添加素材至${state.activeLayer?'叠层 V'+(state.activeLayer+1):'主轨 V1'}`);}}
$('trackLabels').addEventListener('click',chooseLayer);$('trackLabels').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseLayer(e);}});
document.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('Files')){e.preventDefault();document.querySelector('.library').classList.add('drop-target');}});
document.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.querySelector('.library').classList.remove('drop-target');});
document.addEventListener('drop',async e=>{document.querySelector('.library').classList.remove('drop-target');if(!e.dataTransfer.files.length)return;e.preventDefault();if(!desktopRequired())return;try{const paths=await Promise.all([...e.dataTransfer.files].map(f=>api.filePath(f))),valid=paths.filter(Boolean);if(valid.length)await importAssets(valid);else notify('未能读取拖入文件的本地路径。',true);}catch(error){reportError(error);}});
$('undo').onclick=undo;$('redo').onclick=redo;$('splitClip').onclick=splitSelection;$('removeSelection').onclick=removeSelection;
$('moveLeft').onclick=()=>reorder(-1);$('moveRight').onclick=()=>reorder(1);
$('playPause').onclick=()=>state.playing?pause():play();$('goStart').onclick=()=>seek(0);
$('previousFrame').onclick=()=>{pause();seek(state.time-1/project.fps);};$('nextFrame').onclick=()=>{pause();seek(state.time+1/project.fps);};
$('timelineZoom').oninput=e=>{state.zoom=Number(e.target.value);renderTimeline();};
$('zoomIn').onclick=()=>{state.zoom=clamp(state.zoom*1.2,12,160);renderTimeline();};$('zoomOut').onclick=()=>{state.zoom=clamp(state.zoom/1.2,12,160);renderTimeline();};$('fitTimeline').onclick=fitTimeline;
$('openExport').onclick=openExport;$('projectSettings').onclick=openExport;$('closeExport').onclick=()=>$('exportDialog').close();
$('resolutionPreset').onchange=e=>{if(e.target.value==='custom')return;const [w,h]=e.target.value.split('x');$('exportWidth').value=w;$('exportHeight').value=h;};
$('exportWidth').oninput=updateResolutionPreset;$('exportHeight').oninput=updateResolutionPreset;
$('applyCanvas').onclick=()=>applyCanvas(true);$('startExport').onclick=startExport;$('cancelExport').onclick=cancelExport;
$('revealExport').onclick=async()=>{try{await api.revealFile(state.export.path);}catch(error){reportError(error);}};
$('exportAgain').onclick=()=>{state.export.jobId=null;state.export.status='';openExport();};
document.addEventListener('keydown',e=>{const typing=e.target.closest('input,textarea,select,[contenteditable="true"]'),mod=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(state.replacing){if(mod&&['s','z','y','c','v','a'].includes(k))e.preventDefault();return;}if(mod&&k==='s'){e.preventDefault();saveProject(e.shiftKey);return;}if(typing||document.querySelector('dialog[open]'))return;if(mod&&k==='c'){e.preventDefault();timelineEditor?.copy();return;}if(mod&&k==='v'){e.preventDefault();timelineEditor?.paste();return;}if(mod&&k==='a'){e.preventDefault();timelineEditor?.selectAll();return;}if(mod&&k==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(mod&&k==='y'){e.preventDefault();redo();return;}if(e.code==='Space'){e.preventDefault();state.playing?pause():play();}else if(!mod&&k==='s'){e.preventDefault();splitSelection();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeSelection();}else if(e.key==='ArrowLeft'){e.preventDefault();pause();seek(state.time-1/project.fps);}else if(e.key==='ArrowRight'){e.preventDefault();pause();seek(state.time+1/project.fps);}else if(e.key==='Home'){e.preventDefault();seek(0);}else if(e.key==='End'){e.preventDefault();seek(duration());}});
window.addEventListener('beforeunload',e=>{if(dirty()&&!state.export.active&&!state.export.pending&&!state.asr.active&&!state.asr.pending){e.preventDefault();e.returnValue='';}});
new ResizeObserver(()=>{resizePreview();syncMedia(true);}).observe($('previewArea'));
window.addEventListener('resize',()=>renderTimeline());
$('cancelImport').addEventListener('click',async()=>{$('cancelImport').disabled=true;try{await api.cancelImport();}catch(error){reportError(error);}finally{$('cancelImport').hidden=true;updateEngineStatus();}});
if(api){try{api.onExportProgress(exportProgress);if(api.onImportProgress)api.onImportProgress(data=>{$('cancelImport').hidden=!data.active;$('cancelImport').disabled=false;if(data.active)$('statusMessage').textContent=`准备素材 ${data.index}/${data.total} · ${data.name} · ${Math.round((data.ratio||0)*100)}%`;else updateEngineStatus();});if(api.onTranscriptionProgress)api.onTranscriptionProgress(transcriptionProgress);}catch(error){reportError(error);}Promise.resolve(api.getEnvironment()).then(env=>{state.environment=env;updateEngineStatus();}).catch(error=>{$('statusMessage').textContent='桌面引擎连接失败';reportError(error);});}else{$('desktopNotice').hidden=false;updateEngineStatus();}
